The path inside the Amazon S3 bucket pointing to the test-set CSV file. Constraints: • min: 1 • max: 1024 • pattern: [\.\-\!\*\_\'\(\)a-zA-Z0-9][\.\-\!\*\_\'\(\)\/a-zA-Z0-9]*$ modality -&gt; (string) [required] Specifies whether the test-set being imported contains written or spoken data. Possible values: • Text • Audio testSetTags -&gt; (map) A list of tags to add to the test set. You can only add tags when you import/generate a new test set. You can't use the UpdateTestSet operation to update tags. To update tags, use the TagResource operation. Constraints: • min: 0 • max: 200 key -&gt; (string) Constraints: • min: 1 • max: 128 value -&gt; (string) Constraints: • min: 0 • max: 256 JSON Syntax: { "botImportSpecification": { "botName": "string", "roleArn": "string", "dataPrivacy": { "childDirected": true|false }, "errorLogSettings": { "enabled": true|false }, "idleSessionTTLInSeconds": integer, "botTags": {"string": "string" ...}, "testBotAliasTags": {"string": "string" ...} }, "botLocaleImportSpecification": { "botId": "string", "botVersion": "string", "localeId": "string", "nluIntentConfidenceThreshold": double, "voiceSettings": { "engine": "standard"|"neural"|"long-form"|"generative", "voiceId": "string" }, "speechRecognitionSettings": { "speechModelPreference": "Standard"|"Neural"|"Deepgram"|"Advanced", "speechModelConfig": { "deepgramConfig": { "apiTokenSecretArn": "string", "modelId": "string" } } }, "speechDetectionSensitivity": "Default"|"HighNoiseTolerance"|"MaximumNoiseTolerance", "unifiedSpeechSettings": { "speechFoundationModel": { "modelArn": "string", "voiceId": "string" } }, "audioFillerSettings": { "enabled": true|false, "audioType": "MELODY_CHIPPER_CHIME"|"MELODY_CURIOUS_CRAWL"|"MELODY_RISING_RIPPLE"|"MELODY_PATIENT_PING"|"MELODY_PONDERING_PONG"|"TYPING_KINETIC_KEYS"|"TYPING_QUIET_QWERTY", "startDelayInMilliseconds": integer, "minimumPlayDurationInMilliseconds": integer, "responseDeliveryDelayInMilliseconds": integer }, "speakerDiarizationSettings": { "enabled": true|false } }, "customVocabularyImportSpecification": { "botId": "string", "botVersion": "string", "localeId": "string" }, "testSetImportResourceSpecification": { "testSetName": "string", "description": "string", "roleArn": "string", "storageLocation": { "s3BucketName": "string", "s3Path": "string", "kmsKeyArn": "string" }, "importInputLocation": { "s3BucketName": "string", "s3Path": "string" }, "modality": "Text"|"Audio", "testSetTags": {"string": "string" ...} } }
